/* Preserve source paisa through real review/save/ledger UI workflows. */
const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');
const sizes=process.env.DEEP_AUDIT_SMOKE?[[390,844]]:[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]];
const languages=process.env.DEEP_AUDIT_SMOKE?['English + Bangla']:['English','English + Bangla','Bangla'];const port=Number(process.env.DEEP_AUDIT_PORT||4491),output=process.env.DEEP_AUDIT_OUTPUT||'.superpowers/deep-audit/currency-precision',results=[];
async function main(){const {createServer}=await import('vite');const server=await createServer({cacheDir:'.superpowers/currency-browser-cache-'+port,server:{host:'127.0.0.1',port,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});fs.mkdirSync(output,{recursive:true});
try{for(const [width,height]of sizes)for(const theme of ['light','dark'])for(const language of languages){const bn=language==='Bangla',id=width+'-'+theme+'-'+language.replaceAll(' ','');const context=await browser.newContext({viewport:{width,height},hasTouch:width<=1024,colorScheme:theme,reducedMotion:'reduce'});await context.addInitScript(({theme,language})=>{localStorage.setItem('hisabiq-theme',theme);localStorage.setItem('hisabiq-erp-personal-v1',JSON.stringify({mode:'Simple',language,density:'Compact',terminology:'simple',dateView:'transaction'}));},{theme,language});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage();page.setDefaultNavigationTimeout(60000);await page.route('https://fonts.googleapis.com/**',r=>r.abort());const errors=[];page.on('pageerror',e=>errors.push(e.message));const text=(en,bangla)=>bn?bangla:en;const act=e=>width<=1024?e.tap():e.click();
const check=async(name,run)=>{try{await run();assert.deepEqual(errors,[]);results.push({id,name,status:'passed'});}catch(e){results.push({id,name,status:'failed',error:e.message});console.error(id,name,e.message);await page.screenshot({path:path.join(output,id+'-'+name+'.png'),fullPage:true});}};
await check('finance-paisa',async()=>{await page.goto(`http://127.0.0.1:${port}/#/app/finance`,{waitUntil:'domcontentloaded'});await act(page.getByRole('button',{name:text('New transaction','নতুন লেনদেন'),exact:true}));const d=page.getByRole('dialog',{name:new RegExp(text('New finance transaction','নতুন টাকার লেনদেন'))});const amount=d.locator('label').filter({hasText:new RegExp('^'+text('Amount','টাকা'))}).getByRole('textbox');await amount.fill('0.25');await act(d.getByRole('button',{name:text('Review transaction','লেনদেন যাচাই করুন'),exact:true}));await expect(d.getByRole('status'),'review preserves entered paisa').toContainText('৳0.25');await act(d.getByRole('button',{name:text('Confirm finance transaction','লেনদেন নিশ্চিত করুন'),exact:true}));await expect(d).toBeHidden();await act(page.getByRole('tab',{name:text('Loans & Owners','ঋণ ও মালিক'),exact:true}));await expect(page.locator('tbody tr').filter({hasText:'FIN-000189'})).toContainText('+৳0.25');});
await check('party-paisa',async()=>{await page.goto(`http://127.0.0.1:${port}/#/app/parties?id=c4&role=Customer`,{waitUntil:'domcontentloaded'});await act(page.getByRole('button',{name:text('Receive payment','টাকা নিন'),exact:true}));const pay=page.getByRole('dialog',{name:text('Party payment','পক্ষের পেমেন্ট'),exact:true});await pay.getByRole('textbox',{name:text('Payment amount','পেমেন্টের টাকা'),exact:true}).fill('0.25');await act(pay.getByRole('button',{name:text('Review payment','পেমেন্ট যাচাই করুন'),exact:true}));await expect(pay.getByRole('status'),'cash movement shows paisa before confirmation').toContainText('৳0.25');await act(pay.getByRole('button',{name:text('Confirm receive payment','ক্রেতার টাকা নেওয়া নিশ্চিত করুন'),exact:true}));await expect(pay).toBeHidden();const menu=page.getByRole('button',{name:/PAYMENT:1$/});const row=menu.locator(width<640?'xpath=ancestor::div[contains(@class,"rounded-lg") and contains(@class,"border")][1]':'xpath=ancestor::tr[1]');await expect(row.getByTestId('ledger-money-value')).toHaveText('0.25');await act(menu);await act(page.getByRole('button',{name:text('Edit','সম্পাদনা'),exact:true}));const editor=page.getByRole('dialog',{name:text('Party transaction editor','লেনদেন সংশোধন'),exact:true});await expect(editor.getByRole('textbox',{name:text('Corrected payment amount','সংশোধিত পেমেন্টের টাকা'),exact:true})).toHaveValue('0.25');await act(editor.getByRole('button',{name:text('Cancel','বাতিল'),exact:true}));await act(page.getByRole('button',{name:text('Print statement','হিসাব প্রিন্ট'),exact:true}));const statement=page.getByRole('dialog',{name:text('Party ledger statement','পক্ষের হিসাবের বিবরণ'),exact:true});await expect(statement.locator('tbody tr').filter({hasText:'PAYMENT:1'}).locator('td').nth(3)).toHaveText('0.25');await act(statement.getByRole('button',{name:text('Close','বন্ধ করুন'),exact:true}).first());await expect(statement).toBeHidden();});
await context.tracing.stop(results.some(r=>r.id===id&&r.status==='failed')?{path:path.join(output,id+'-trace.zip')}:{});await context.close();console.log(id,results.filter(r=>r.id===id).map(r=>r.name+':'+r.status).join(','));
}}finally{fs.writeFileSync(path.join(output,'results.json'),JSON.stringify(results,null,2));await browser.close();await server.close();}console.log(results.length+' journeys; '+results.filter(r=>r.status==='failed').length+' failed');assert.equal(results.filter(r=>r.status==='failed').length,0);}
main().catch(e=>{console.error(e);process.exitCode=1;});
